CREATE OR REPLACE TABLE prd-izipay-data-storage-pv.master_product.m_terminal( 
process_date DATE NOT NULL OPTIONS(description= 'Fecha de procesamiento de la tabla (día actual) que contiene data al cierre del día anterior'), 
cod_comercio STRING  OPTIONS(description= 'Código del comercio adaptado a los 7 primeros dígitos'), 
cod_comercio_mccenter STRING  OPTIONS(description= 'Código del comercio original proveniente del mccenter'), 
adq_cajero_corr STRING  OPTIONS(description= 'Tipo de adquirente/cajero corresponsal'), 
categoria_comercio STRING  OPTIONS(description= 'Categoría del comercio según clasificación'), 
party_id_izi STRING  OPTIONS(description= 'Número de identificación del comercio (RUC, DNI, Carnet de extranjería)'), 
telefono_comercio BYTES  OPTIONS(description= 'Teléfono del comercio'), 
contacto_comercio BYTES  OPTIONS(description= 'Indica el nombre del contacto del comercio'), 
perfil_comercio STRING  OPTIONS(description= 'Indica las opciones que tiene habilitado el comercio'), 
perfil_descarga STRING  OPTIONS(description= 'Indica la actualización del POS del comercio'), 
cod_terminal STRING  OPTIONS(description= 'Código de terminal'), 
num_serie_sistema STRING  OPTIONS(description= 'Número de serie del POS (inicial, solo los 8 últimos dígitos). Es la que figura en el sistema MCCenter, puede ser la serie corta, últimos 8 ó la serie autogenerada del mpos'), 
tipo_conexion_mcc STRING  OPTIONS(description= 'Tipo de conexión del POS específico'), 
tipo_conexion STRING  OPTIONS(description= 'Tipo de conexión del POS'), 
descripcion_terminal STRING  OPTIONS(description= 'Nombre del tipo de terminal/equipo del comercio'), 
fecha_ult_conex_mccenter DATE  OPTIONS(description= 'Fecha de última conexión con Mccenter'), 
fecha_ult_trx_financiera DATE  OPTIONS(description= 'Fecha de última transacción financiera'), 
fecha_ult_trx_administrativa DATE  OPTIONS(description= 'Fecha de última transacción administrativa'), 
situacion_terminal STRING  OPTIONS(description= 'Situación de terminal según la última transacción de POS'), 
modelo_terminal_general STRING  OPTIONS(description= 'Modelo del equipo (general) proveniente del AS400'), 
modelo_terminal_mcc STRING  OPTIONS(description= 'Modelo del equipo (código del modelo) proveniente del MCCENTER'), 
version_software STRING  OPTIONS(description= 'Versión del Software base (origen: Mccenter)'), 
version_firmware_contactless STRING  OPTIONS(description= 'Indica la versión de Firmware contactless que posee el terminal'), 
nro_chip STRING  OPTIONS(description= 'Número del chip que se encuentra en el equipo.'), 
nro_telefono_chip BYTES  OPTIONS(description= 'Número de teléfono del chip del equipo'), 
operador_chip STRING  OPTIONS(description= 'Operador del chip del equipo (si aplica). Nombre comercial de la compañía telefónica a la cuál pertenece el chip del equipo'), 
estado_comercio STRING  OPTIONS(description= 'Estado del comercio'), 
estado_logico_comercio STRING  OPTIONS(description= 'Estado lógico del comercio'), 
estado_terminal STRING  OPTIONS(description= 'Estado del terminal'), 
estado_logico_terminal STRING  OPTIONS(description= 'Estado lógico del terminal'), 
tipo_aplicacion STRING  OPTIONS(description= 'Tipo de aplicación de los terminales'), 
desc_aplicacion STRING  OPTIONS(description= 'Descripción de la aplicación de los terminales'), 
num_serie_mpos STRING  OPTIONS(description= 'Número de serie del terminal POS. Autogenerado de los MPOS'), 
cod_version_flujo STRING  OPTIONS(description= 'ID correspondiente a la versión de flujo (Permite identificar si está actualizado)'), 
cod_version_main STRING  OPTIONS(description= 'ID correspondiente a la versión de carga base (Permite identificar si está actualizado)'), 
num_serie_real STRING  OPTIONS(description= 'Número de serie completa del POS, la que se aprecia visualmente en el terminal y al cuál se le puede aplicar las actualizaciones respectivas.'), 
marca STRING  OPTIONS(description= 'Marca del equipo'), 
ind_propina STRING  OPTIONS(description= 'Indica el tipo de opción de recibimiento de propina'), 
fecha_actualizacion_app DATE  OPTIONS(description= 'Fecha de actualización de la aplicación'), 
hora_actualizacion_app STRING  OPTIONS(description= 'Hora de actualización de la aplicación en formato 24h'), 
fecha_hora_actualizacion_app DATETIME  OPTIONS(description= 'Fecha y hora de actualización de la aplicación'), 
fecha_ult_actualizacion DATE  OPTIONS(description= 'Fecha de última actualización de App'), 
hora_ult_actualizacion STRING  OPTIONS(description= 'Hora de última actualización de la aplicación'), 
fecha_hora_ult_actualizacion DATETIME  OPTIONS(description= 'Fecha y hora de última actualización de la aplicación'), 
cod_version_app STRING  OPTIONS(description= 'ID correspondiente a la versión de la aplicación'), 
version_app STRING  OPTIONS(description= 'Versión de la aplicación'), 
version_flujo STRING  OPTIONS(description= 'Versión del flujo'), 
cod_marguesi STRING  OPTIONS(description= 'Código del activo fijo. Marquesi del equipo'), 
fecha_compra DATE  OPTIONS(description= 'Fecha de compra'), 
situacion_as400 STRING  OPTIONS(description= 'Estado según cruce de la información del terminal con la del AS400. (BAJA, ALQUILER, VENTA, ACTIVO)'), 
cosecha STRING  OPTIONS(description= 'Campo calculado que permite identificar la antigüedad de un comercio afiliado de acuerdo a su fecha de apertura y la fecha actual'), 
oficina_comercio STRING  OPTIONS(description= 'Ubicación de oficina asociada al comercio'), 
modelo_terminal_especifico STRING  OPTIONS(description= 'Modelo del equipo (específico), se detalla el modelo específico del terminal según una lista estática de modelos antiguos, caso contrario es el modelo proveniente del MCCENTER'), 
fecha_instalacion DATE  OPTIONS(description= 'Fecha de instalación'), 
cant_intento INT64  OPTIONS(description= 'Cantidad de intentos que realizó el terminal para actualizarse'), 
flag_terminal_activo BOOLEAN  OPTIONS(description= 'Flag que indica si el terminal ha transaccionado en los últimos 3 meses'), 
flag_facturacion BOOLEAN  OPTIONS(description= 'Flag que indica si el comercio admite facturación. true = sí, false, no'), 
flag_software_contactless BOOLEAN  OPTIONS(description= 'Flag que indica si el POS tiene Software contactless'), 
flag_hardware_contactless BOOLEAN  OPTIONS(description= 'Flag que Indica si el POS tiene Hardware contactless'), 
flag_pre_autorizacion_comercio BOOLEAN  OPTIONS(description= 'Flag que indica si aplica la pre autorización a nivel del comercio'), 
flag_pre_autorizacion_terminal BOOLEAN  OPTIONS(description= 'Flag que indica si aplica la pre autorización a nivel del terminal'), 
flag_dig_manual_comercio BOOLEAN  OPTIONS(description= 'Flag que indica si aplica la digitación manual a nivel del comercio'), 
flag_dig_manual_terminal BOOLEAN  OPTIONS(description= 'Flag que indica si aplica la digitación manual a nivel del terminal'), 
flag_version_actualizada BOOLEAN  OPTIONS(description= 'Flag que indica si la versión se ha actualizado'), 
flag_pos_emv_diners BOOLEAN  OPTIONS(description= 'Flag que indica si el comercio tiene POS EMV DINERS'), 
flag_pinpad BOOLEAN  OPTIONS(description= 'Flag que indica si el terminal tiene pinpad o no'), 
flag_multicomercio BOOLEAN  OPTIONS(description= 'Flag que indica si el terminal es multicomercio. Ocurre cuando el POS está asignado a más de 1 código de comercio'), 
record_source STRING NOT NULL OPTIONS(description= 'Dato de Auditoría: Descripción del aplicativo origen de los datos.'), 
load_date DATETIME NOT NULL OPTIONS(description= 'Fecha y hora de inserción del registro en el modelo'), 
creation_user STRING NOT NULL OPTIONS(description= 'Usuario que crea el registro en la BD'), 
)
PARTITION BY process_date
CLUSTER BY cod_comercio,party_id_izi,num_serie_sistema,num_serie_real
OPTIONS (description ='Maestro de terminales. Contiene todos los equipos asociados a cada comercio afiliado con su configuración, corresponde a la última foto con data del cierre del día anterior');